export const mainIds=Array.from({length:41},(_,i)=>'S'+String(i).padStart(2,'0'));
export const shortened=mainIds.filter(id=>!['S08','S10','S26','S31','S34'].includes(id));
export function nextPosition(state,slides,direction=1,path=mainIds){const s=slides.find(s=>s.id===state.slideId);const max=s.buildSteps.length-1;let {slideId,buildStep}=state;if(direction>0){if(buildStep<max)buildStep++;else{const i=path.indexOf(slideId);const target=i>=0?path[i+1]:slideId.startsWith('S')?path.find(id=>id>slideId):null;if(target){slideId=target;buildStep=0;}}}else if(buildStep>0)buildStep--;else{const i=path.indexOf(slideId);const target=i>=0?path[i-1]:slideId.startsWith('S')?path.findLast(id=>id<slideId):null;if(target){slideId=target;buildStep=slides.find(s=>s.id===slideId).buildSteps.length-1;}}return {slideId,buildStep};}
export function parsePosition(hash,slides){const m=hash.match(/^#([SX]\d{2})(?:\/(\d+))?$/);const slide=slides.find(s=>s.id===m?.[1])||slides[0];return {slideId:slide.id,buildStep:Math.min(Math.max(Number(m?.[2]||0),0),slide.buildSteps.length-1)};}
